dashboard.definition:
{
	"title": "DLP and Cloud Native Security",
	"description": "Expose data-loss risk and cloud-native workload controls in one operational view.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#16283c",
				"strokeColor": "rgba(53,207,245,0.42)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Hybrid Mesh Firewalling",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/hybrid-mesh-firewalling.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#e8f1fb",
				"markdown": "# DLP and Cloud Native Security\nExpose data-loss risk and cloud-native workload controls in one operational view."
			}
		},
		"viz_secure_networking_secure_access_dlp_findings": {
			"type": "splunk.table",
			"title": "Secure Access DLP Findings",
			"dataSources": {
				"primary": "ds_secure_networking_secure_access_dlp_findings"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Summarizes Secure Access DLP findings by severity, action, rule, data classification, application, and traffic direction."
		},
		"viz_secure_networking_segmentation_secure_workload_alerts_by_type": {
			"type": "splunk.table",
			"title": "Segmentation Secure Workload Alerts by Type",
			"dataSources": {
				"primary": "ds_secure_networking_segmentation_secure_workload_alerts_by_type"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Breaks down Cisco Secure Workload (Tetration) alerts by type and severity — compliance policy violations, anomalous traffic, and sensor issues — across the micro-segmented workload fabric."
		},
		"viz_security_microseg_tetration_alerts_by_severity_type": {
			"type": "splunk.bar",
			"title": "Secure Workload Alerts by Severity and Type",
			"dataSources": {
				"primary": "ds_security_microseg_tetration_alerts_by_severity_type"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "bottom",
				"seriesColors": [
					"#ff7169",
					"#ff9a4a",
					"#2563EB",
					"#8bd45b"
				],
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"stackMode": "unstacked"
			},
			"description": "Cisco Secure Workload (Tetration) alerts split by type (COMPLIANCE, TRAFFIC, SENSOR) and severity (critical, high, medium, and low), sourced from Cisco Secure Workload."
		},
		"viz_secure_networking_cloud_native_security_activity": {
			"type": "splunk.bar",
			"title": "Cloud Native Security Activity by Provider",
			"dataSources": {
				"primary": "ds_secure_networking_cloud_native_security_activity"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "bottom",
				"seriesColors": [
					"#ff9a4a",
					"#2563EB",
					"#8bd45b"
				],
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"stackMode": "stacked"
			},
			"description": "Summarizes confirmed native AWS, Azure, and GCP/Google Workspace security activity by provider and sourcetype, covering threat detections, audit and identity events, configuration findings, and vulnerability…"
		},
		"viz_design_context": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "**Audience:** Cloud security, SOC, and workload-security teams  •  **Sources:** Secure Access, Secure Workload, and cloud-native security telemetry  •  **Reading guide:** Review severity patterns first, then investigate DLP findings and workload evidence.  •  **Freshness:** Uses the dashboard time range"
			}
		},
		"viz_design_section": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "### Data and workload risk\nReview severity patterns first, then investigate DLP findings and workload evidence."
			}
		}
	},
	"dataSources": {
		"ds_secure_networking_secure_access_dlp_findings": {
			"name": "Secure Networking - Secure Access DLP Findings",
			"options": {
				"ref": "secure_networking_secure_access_dlp_findings",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_secure_networking_segmentation_secure_workload_alerts_by_type": {
			"name": "Secure Networking - Segmentation Secure Workload Alerts by Type",
			"options": {
				"ref": "secure_networking_segmentation_secure_workload_alerts_by_type",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_security_microseg_tetration_alerts_by_severity_type": {
			"name": "Security - Microsegmentation - Secure Workload Alerts by Severity and Type",
			"options": {
				"ref": "security_microseg_tetration_alerts_by_severity_type",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_secure_networking_cloud_native_security_activity": {
			"name": "Secure Networking - Cloud Native Security Activity by Provider",
			"options": {
				"ref": "secure_networking_cloud_native_security_activity",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#07101d",
					"display": "auto-scale",
					"height": 1198,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 118
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 19,
							"w": 80,
							"h": 80
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 132,
							"y": 8,
							"w": 1268,
							"h": 102
						},
						"type": "block"
					},
					{
						"item": "viz_design_context",
						"position": {
							"x": 20,
							"y": 138,
							"w": 1400,
							"h": 92
						},
						"type": "block"
					},
					{
						"item": "viz_design_section",
						"position": {
							"x": 20,
							"y": 250,
							"w": 1400,
							"h": 72
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_secure_access_dlp_findings",
						"position": {
							"x": 20,
							"y": 342,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_segmentation_secure_workload_alerts_by_type",
						"position": {
							"x": 730,
							"y": 342,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_security_microseg_tetration_alerts_by_severity_type",
						"position": {
							"x": 20,
							"y": 770,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_cloud_native_security_activity",
						"position": {
							"x": 730,
							"y": 770,
							"w": 690,
							"h": 408
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": false,
		"hideExport": false
	}
}
